    // W3C SCXML feature flags
    const HAS_PARALLEL_STATES: bool = false;
    const NEEDS_SCRIPT_ENGINE: bool = false;
    const NEEDS_DATA_MODEL_INIT: bool = false;
    // The same fact the generate manifest publishes as `needs_event_scheduler`.
    // A `build.rs` consumer never sees that manifest — `compile_scxml` returns
    // `()` — so without this constant a host had no route to the knowledge that
    // its driving loop must call `tick()` rather than `step()`.
    const NEEDS_EVENT_SCHEDULER: bool = false;
    // The generate manifest's `needs_parent`: what a root-start policy reads.
    const NEEDS_PARENT: bool = false;

    // ======================================================================
    // Static metadata methods (W3C SCXML document structure)
    // ======================================================================

    fn initial_state() -> Self::State {
        // The runtime entry state and the type's `Default` derive are one
        // concept, sourced from one computation (`default_state_id`) so
        // they can never diverge: `<scxml initial>`, or the first sorted
        // state when the initial attribute is unset.
        StaticSendParamsState::Idle
    }

    fn is_final_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    fn get_parent(state: Self::State) -> Option<Self::State> {
        match state {
            _ => None,
        }
    }

    // W3C SCXML 3.3: a <state> with child states — exactly the states that have
    // an initial transition. A <parallel> is not compound.
    fn is_compound_state(state: Self::State) -> bool {
        match state {
            _ => false,
        }
    }

    // §scxml-D-getChildStates: a state's <state>, <parallel> and <final>
    // children, in document order — for a <parallel>, its regions.
    fn get_child_states(state: Self::State) -> &'static [Self::State] {
        match state {
            _ => &[],
        }
    }

    // §scxml-3.3: a compound state's initial transition target, as written —
    // the engine's entry procedures dereference a <history> among them.
    fn get_initial_targets(
        state: Self::State,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match state {
            _ => &[],
        }
    }

    // §scxml-3.2: the target of the document's own initial transition, as written.
    fn get_document_initial_targets(
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        &[::sce_rust_runtime::EntryTarget::State(
            StaticSendParamsState::Idle,
        )]
    }

    // §scxml-3.10: the state a <history> is declared in.
    fn get_history_parent(history: Self::History) -> Self::State {
        match history {}
    }

    // §scxml-3.10.2: a <history>'s default transition target, as written.
    fn get_history_default_targets(
        history: Self::History,
    ) -> &'static [::sce_rust_runtime::EntryTarget<Self::State, Self::History>] {
        match history {}
    }

    fn get_document_order(state: Self::State) -> u32 {
        match state {
            StaticSendParamsState::Idle => 0,
        }
    }

    fn get_event_name(event: Self::Event) -> &'static str {
        match event {
            StaticSendParamsEvent::Bad => "bad",
            StaticSendParamsEvent::Echo => "echo",
            StaticSendParamsEvent::ErrorExecution => "error.execution",
            StaticSendParamsEvent::Go => "go",
            StaticSendParamsEvent::Partial => "partial",
            StaticSendParamsEvent::Null => "",
        }
    }

    fn get_event_from_name(name: &str) -> Option<Self::Event> {
        match name {
            "bad" => Some(StaticSendParamsEvent::Bad),
            "echo" => Some(StaticSendParamsEvent::Echo),
            "error.execution" => Some(StaticSendParamsEvent::ErrorExecution),
            "go" => Some(StaticSendParamsEvent::Go),
            "partial" => Some(StaticSendParamsEvent::Partial),
            _ => None,
        }
    }

    fn get_state_name(state: Self::State) -> &'static str {
        match state {
            StaticSendParamsState::Idle => "idle",
        }
    }

    // The inverse of the table above, emitted from the same loop over the
    // document's states so the two age together. It is what lets a host turn a
    // recorded configuration back into the `StateChain` `enter_at` takes.
    fn get_state_from_name(name: &str) -> Option<Self::State> {
        match name {
            "idle" => Some(StaticSendParamsState::Idle),
            _ => None,
        }
    }

    fn null_event() -> Self::Event {
        StaticSendParamsEvent::Null
    }

    // ======================================================================
    // Run-time state the entry procedures read
    // ======================================================================

    // §scxml-3.10: what a <history> recorded when its parent was last exited;
    // None before that ever happened.
    fn history_value(&self, history: Self::History) -> Option<&[Self::State]> {
        match history {}
    }

    // NL→IR Item C1 Path A: store the current event's typed `_event.data`
    // payload so native transition guards can read it without a script
    // engine. Called by the engine's pop loop for every dequeued event;
    // events injected without a typed payload carry the `#[default] None`
    // variant, against which the variant-specific guards simply fail.
    fn populate_event_payload(&mut self, payload: &Self::Payload) {
        self.pending_payload = payload.clone();
    }

    // NL→IR Item C1 Path A: …and when no typed payload rode with the event,
    // read that view out of the `data` every other producer fills — `<send>`
    // with `<param>`, an invoke forwarding either way, autoforward, BasicHTTP,
    // mesh. A payload that does not read as this event's schema is returned as
    // a refusal, which the engine raises as `error.execution`.
    fn lift_event_payload(
        &mut self,
        event: Self::Event,
        data: &str,
    ) -> ::core::result::Result<(), ::sce_rust_runtime::event_payload::PayloadRefusal> {
        // A typed payload already bound the view, so the producer was the inject
        // seam and there is nothing to read out of `data`.
        if self.pending_payload != StaticSendParamsPayload::None {
            return Ok(());
        }
        match event {
            StaticSendParamsEvent::Echo => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload = StaticSendParamsPayload::Echo(StaticSendParamsEchoPayload {
                    total: fields.unsigned::<u32>("total")?,
                    ok: fields.truth("ok")?,
                    tag: fields.text("tag")?,
                });
            }
            StaticSendParamsEvent::Partial => {
                let fields = ::sce_rust_runtime::event_payload::PayloadFields::decode(data)?;
                self.pending_payload =
                    StaticSendParamsPayload::Partial(StaticSendParamsPartialPayload {
                        total: fields.unsigned::<u32>("total")?,
                        part: fields.unsigned::<u8>("part")?,
                    });
            }
            _ => {}
        }
        Ok(())
    }

