    fn first_enabled_transition(
        &mut self,
        state: Self::State,
        event: Self::Event,
        engine: &mut sce_rust_runtime::Engine<Self>,
    ) -> Option<::sce_rust_runtime::EnabledTransition<Self::State, Self::History>> {
        match state {
            StaticSendParamsState::Idle => {
                if event == StaticSendParamsEvent::Go {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[],
                            transition_index: 0,
                            has_actions: true,
                            is_internal: true,
                        });
                    }
                }
                if event == StaticSendParamsEvent::Bad {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[],
                            transition_index: 1,
                            has_actions: true,
                            is_internal: true,
                        });
                    }
                }
                if event == StaticSendParamsEvent::Echo {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[],
                            transition_index: 2,
                            has_actions: true,
                            is_internal: true,
                        });
                    }
                }
                if event == StaticSendParamsEvent::Partial {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[],
                            transition_index: 3,
                            has_actions: true,
                            is_internal: true,
                        });
                    }
                }
                if event == StaticSendParamsEvent::ErrorExecution {
                    {
                        return Some(::sce_rust_runtime::EnabledTransition {
                            source: state,
                            targets: &[],
                            transition_index: 4,
                            has_actions: true,
                            is_internal: true,
                        });
                    }
                }
                None
            }
            _ => None,
        }
    }

